"""Dataset figure: how strongly the companies in each benchmark are correlated.

Reproduces the report's correlation figure from the OR-Library files in
``evolution_strategy/data`` only. No experiment results are needed and no
optimization is run.

Run from the repository root::

    python -m evolution_strategy.plot_datasets

Panel (a) is the correlation matrix of one dataset (port1 by default).
Panel (b) shows, for each of the five datasets, the spread of all pairwise
correlations C_ij with i < j (each pair counted once, diagonal excluded).
"""

from __future__ import annotations

import argparse
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt

from evolution_strategy.portfolio import Portfolio
from evolution_strategy.results import PORTFOLIOS
from logger import get_logger

logger = get_logger(__name__)

DATASETS = ("port1", "port2", "port3", "port4", "port5")

# Stock-market index behind each file, as described by Chang, Meade, Beasley and
# Sharaiha (2000), the paper the OR-Library portfolio page cites for these files.
MARKETS = {
    "port1": "Hang Seng",
    "port2": "DAX 100",
    "port3": "FTSE 100",
    "port4": "S&P 100",
    "port5": "Nikkei 225",
}

FIGURE_NAME = "dataset_correlations.png"
DEFAULT_OUT_DIR = Path(__file__).resolve().parent / "figures"

# Neutral inks for a single-series chart; the heatmap uses a diverging map
# centred on 0 so that only negative correlations look blue.
INK = "#1f1f1f"
LINE = "#4d4d4d"
FILL = "#d9d9d9"
GRID = "#e6e6e6"


def correlation_matrix(portfolio: list[Portfolio]) -> list[list[float]]:
    """Full n x n correlation matrix C (symmetric, ones on the diagonal)."""
    return [list(company.correlations) for company in portfolio]


def pairwise_correlations(portfolio: list[Portfolio]) -> list[float]:
    """Every off-diagonal correlation C_ij with i < j, each pair once."""
    n = len(portfolio)
    return [portfolio[i].correlations[j] for i in range(n) for j in range(i + 1, n)]


def _plot_heatmap(ax, fig, portfolio: list[Portfolio], dataset: str) -> None:
    matrix = correlation_matrix(portfolio)
    n = len(matrix)
    image = ax.imshow(matrix, cmap="coolwarm", vmin=-1.0, vmax=1.0, interpolation="nearest")

    # imshow counts from 0; label the ticks with the 1-based company numbers.
    positions = [0, *range(4, n, 5)]
    ax.set_xticks(positions, [str(p + 1) for p in positions])
    ax.set_yticks(positions, [str(p + 1) for p in positions])
    ax.set_xlabel(f"Company (1–{n})")
    ax.set_ylabel(f"Company (1–{n})")
    ax.set_title(f"(a) {dataset} ({MARKETS[dataset]}): correlation matrix",
                 loc="left", fontsize=11, color=INK)

    colorbar = fig.colorbar(image, ax=ax, fraction=0.046, pad=0.04,
                            ticks=[-1.0, -0.5, 0.0, 0.5, 1.0])
    colorbar.set_label("Correlation $C_{ij}$")
    colorbar.outline.set_linewidth(0.5)


def _plot_boxplots(ax, portfolios: dict[str, list[Portfolio]]) -> None:
    data = [pairwise_correlations(portfolios[dataset]) for dataset in DATASETS]
    ax.boxplot(
        data,
        widths=0.5,
        patch_artist=True,
        boxprops={"facecolor": FILL, "edgecolor": LINE, "linewidth": 1.0},
        medianprops={"color": INK, "linewidth": 1.6},
        whiskerprops={"color": LINE, "linewidth": 1.0},
        capprops={"color": LINE, "linewidth": 1.0},
        flierprops={"marker": "o", "markersize": 2.5, "markerfacecolor": LINE,
                    "markeredgecolor": "none", "alpha": 0.45},
    )
    labels = [
        f"{dataset}\n{MARKETS[dataset]}\nn = {len(portfolios[dataset])}"
        for dataset in DATASETS
    ]
    ax.set_xticks(range(1, len(DATASETS) + 1), labels)
    ax.axhline(0.0, color=LINE, linewidth=0.8, zorder=0)
    ax.yaxis.grid(True, color=GRID, linewidth=0.8)
    ax.set_axisbelow(True)
    ax.set_ylabel("Pairwise correlation $C_{ij}$ ($i < j$)")
    ax.set_title("(b) Pairwise correlations in each dataset",
                 loc="left", fontsize=11, color=INK)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)


def plot_dataset_correlations(
    portfolios: dict[str, list[Portfolio]],
    out_path: Path,
    heatmap_dataset: str = "port1",
) -> Path:
    """Draw both panels and save them as one PNG (300 dpi). Returns the path."""
    if heatmap_dataset not in DATASETS:
        raise ValueError(f"Unknown dataset {heatmap_dataset!r}; expected one of {DATASETS}")

    fig, (heatmap_ax, box_ax) = plt.subplots(
        1, 2, figsize=(12.5, 4.9), gridspec_kw={"width_ratios": [1.0, 1.3]}
    )
    _plot_heatmap(heatmap_ax, fig, portfolios[heatmap_dataset], heatmap_dataset)
    _plot_boxplots(box_ax, portfolios)
    fig.tight_layout()

    out_path = Path(out_path)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(out_path, dpi=300, bbox_inches="tight")
    plt.close(fig)
    logger.info(f"Saved dataset correlation plot: {out_path}")
    return out_path


def main(argv: list[str] | None = None) -> None:
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--out-dir", type=Path, default=DEFAULT_OUT_DIR,
                        help=f"Folder for {FIGURE_NAME} (default: evolution_strategy/figures)")
    parser.add_argument("--heatmap-dataset", choices=DATASETS, default="port1",
                        help="Dataset shown in panel (a)")
    args = parser.parse_args(argv)

    plot_dataset_correlations(PORTFOLIOS, args.out_dir / FIGURE_NAME,
                              args.heatmap_dataset)
    logger.info("Done. Only the OR-Library data files were read; no optimization was run.")


if __name__ == "__main__":
    main()
